'use strict';
const DB_NAME='mi-espacio-estudio', DB_VERSION=2, STORE='records', FILE_STORE='attachments';
let db, data={units:[],classes:[],notes:{},cards:[],agenda:[],aiDocuments:[]}, page='home', activeUnit=null, activeClass=null, detailTab='material', searchText='', tagFilter='', dialogMode='', editingId=null;
const $=s=>document.querySelector(s), view=$('#view');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random().toString(36).slice(2)}`;
const showToast=msg=>{const t=$('#toast');t.textContent=msg;t.style.display='block';clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>t.style.display='none',2700)};
function request(r){return new Promise((resolve,reject)=>{r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open(DB_NAME,DB_VERSION);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE);if(!d.objectStoreNames.contains(FILE_STORE))d.createObjectStore(FILE_STORE,{keyPath:'id'})};r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
async function readData(){const tx=db.transaction(STORE,'readonly');const x=await request(tx.objectStore(STORE).get('data'));return {...{units:[],classes:[],notes:{},cards:[],agenda:[],aiDocuments:[]},...(x||{})}}
async function save(){return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error||new Error('Error en IndexedDB'));tx.onabort=()=>reject(tx.error||new Error('Se canceló el guardado'));tx.objectStore(STORE).put(data,'data')})}
function allTags(){return [...new Set(data.classes.flatMap(c=>c.tags||[]))].sort((a,b)=>a.localeCompare(b,'es'))}
function tagHtml(tags){return tags?.length?`<div class="chiprow">${tags.map(t=>`<span class="chip">${esc(t)}</span>`).join('')}</div>`:''}
function placeholder(name,description){return `<section class="card empty"><div class="symbol">◇</div><h2>${name}</h2><p class="muted">${description}</p><p class="notice">Esta sección está planificada para los siguientes bloques. Todavía no almacena información.</p></section>`}
function render(){const names={home:'Inicio',classes:'Mis clases',unit:'Unidad',detail:'Clase',study:'Estudiar',agenda:'Agenda',settings:'Configuración'};$('#pageTitle').textContent=names[page]||'Inicio';document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===({unit:'classes',detail:'classes'}[page]||page)));if(page==='home')home();else if(page==='classes')classes();else if(page==='unit')unitDetail();else if(page==='detail'){classDetail();if(detailTab==='material')loadAttachments();}else if(page==='settings')settings();else if(page==='study'){if(reviewSession)renderReview();else studyView();}else if(page==='agenda')agendaView();}
function navigate(to){page=to;render();window.scrollTo(0,0)}
function home(){const latest=[...data.classes].sort((a,b)=>(b.updatedAt||'').localeCompare(a.updatedAt||''))[0];view.innerHTML=`<section class="card hero"><span class="eyebrow">Tu asignatura</span><h2>Todo tu estudio, en un lugar</h2><p class="muted">Organiza las clases y encuentra sus contenidos por unidades o etiquetas.</p><button class="btn" data-action="go-classes">Ver mis clases</button></section><div class="statgrid"><div class="stat"><b>${data.units.length}</b><span>Unidades</span></div><div class="stat"><b>${data.classes.length}</b><span>Clases</span></div></div><div class="sectionhead"><h2>Continuar</h2></div>${latest?`<section class="card"><button class="tap" data-action="open-class" data-id="${esc(latest.id)}"><div class="titleline">${esc(latest.title)}</div><p class="muted">${esc(data.units.find(u=>u.id===latest.unitId)?.title||'Unidad')}</p>${tagHtml(latest.tags)}</button></section>`:`<section class="card empty"><p class="muted">Todavía no tienes clases. Crea tu primera unidad y después añade una clase.</p><button class="btn" data-action="new-unit">Crear primera unidad</button></section>`}<div class="sectionhead"><h2>Repasar</h2></div><section class="card"><p class="muted">${dueCards().length} tarjetas pendientes de repaso.</p><button class="btn" data-action="go-study">Ir a estudiar</button></section><div class="sectionhead"><h2>Agenda</h2></div><section class="card"><p class="muted">${(data.agenda||[]).filter(x=>!x.done&&x.date&&x.date>=localDay()).length} actividades próximas con fecha.</p><button class="btn secondary" data-action="go-agenda">Ver agenda</button></section>`}
function classes(){let matches=data.classes.filter(c=>(c.title+' '+(c.tags||[]).join(' ')).toLocaleLowerCase('es').includes(searchText.toLocaleLowerCase('es'))&&(!tagFilter||(c.tags||[]).includes(tagFilter)));const unitIds=new Set(matches.map(c=>c.unitId));const filtered=data.units.filter(u=>!tagFilter&&(!searchText||u.title.toLocaleLowerCase('es').includes(searchText.toLocaleLowerCase('es')))||unitIds.has(u.id));view.innerHTML=`<div class="sectionhead"><h2>Unidades</h2><button class="btn small" data-action="new-unit">+ Unidad</button></div><input class="search" id="search" aria-label="Buscar unidades, clases o etiquetas" placeholder="Buscar clases o etiquetas..." value="${esc(searchText)}"><div class="chiprow"><button class="chip ${!tagFilter?'selected':''}" data-tag="">Todas</button>${allTags().map(t=>`<button class="chip ${tagFilter===t?'selected':''}" data-tag="${esc(t)}">${esc(t)}</button>`).join('')}</div><div style="height:14px"></div>${filtered.length?filtered.map(u=>`<section class="card"><button class="tap" data-action="open-unit" data-id="${esc(u.id)}"><div class="row"><div><div class="titleline">${esc(u.title)}</div><p class="muted">${data.classes.filter(c=>c.unitId===u.id).length} clases</p></div><span aria-hidden="true">›</span></div></button><div class="buttonrow"><button class="btn secondary small" data-action="new-class" data-id="${esc(u.id)}">+ Clase</button><button class="btn ghost small" data-action="edit-unit" data-id="${esc(u.id)}">Editar</button></div>${(searchText||tagFilter)?matches.filter(c=>c.unitId===u.id).map(c=>`<div class="listitem"><button class="tap" data-action="open-class" data-id="${esc(c.id)}">${esc(c.title)}${tagHtml(c.tags)}</button></div>`).join(''):''}</section>`).join(''):`<section class="card empty"><div class="symbol">▤</div><p class="muted">${data.units.length?'No se encontraron resultados.':'Todavía no hay unidades creadas.'}</p></section>`}`;const s=$('#search');s?.addEventListener('input',e=>{const pos=e.target.selectionStart;searchText=e.target.value;classes();const next=$('#search');next.focus();next.setSelectionRange(pos,pos)})}
function unitDetail(){const u=data.units.find(x=>x.id===activeUnit);if(!u)return navigate('classes');const arr=data.classes.filter(c=>c.unitId===u.id);view.innerHTML=`<button class="back" data-action="go-classes">‹ Todas las unidades</button><section class="card"><div class="row"><h2>${esc(u.title)}</h2><button class="btn ghost small" data-action="edit-unit" data-id="${esc(u.id)}">Editar</button><button class="btn danger small" data-action="delete-unit" data-id="${esc(u.id)}">Eliminar</button></div><p class="muted">${arr.length} clases · Resumen de unidad editable aquí</p><button class="btn secondary" data-action="edit-note" data-note="unit:${esc(u.id)}">Abrir resumen de unidad</button></section><div class="sectionhead"><h2>Clases</h2><button class="btn small" data-action="new-class" data-id="${esc(u.id)}">+ Clase</button></div>${arr.length?arr.map(c=>`<section class="card"><button class="tap" data-action="open-class" data-id="${esc(c.id)}"><div class="titleline">${esc(c.title)}</div><p class="muted">${c.date?esc(c.date):'Sin fecha'}</p>${tagHtml(c.tags)}</button><div class="buttonrow" style="margin-top:12px"><button class="btn secondary small" data-action="edit-class" data-id="${esc(c.id)}">Editar</button><button class="btn danger small" data-action="delete-class" data-id="${esc(c.id)}">Eliminar</button></div></section>`).join(''):`<section class="card empty"><p class="muted">Aún no hay clases en esta unidad.</p><button class="btn" data-action="new-class" data-id="${esc(u.id)}">Crear una clase</button></section>`}`}
function classDetail(){const c=data.classes.find(x=>x.id===activeClass);if(!c)return navigate('classes');const u=data.units.find(x=>x.id===c.unitId);view.innerHTML=`<button class="back" data-action="open-unit" data-id="${esc(c.unitId)}">‹ ${esc(u?.title||'Unidades')}</button><section class="card"><div class="row"><div><span class="eyebrow">CLASE</span><h2>${esc(c.title)}</h2></div><button class="btn secondary small" data-action="edit-class" data-id="${esc(c.id)}">Editar</button><button class="btn danger small" data-action="delete-class" data-id="${esc(c.id)}">Eliminar</button></div><p class="muted">${c.date?esc(c.date):'Sin fecha'}</p>${tagHtml(c.tags)}</section><div class="detailtabs">${[['material','Material'],['notes','Apuntes'],['cards','Flashcards'],['ai','IA']].map(([k,t])=>`<button class="${detailTab===k?'active':''}" data-tab="${k}">${t}</button>`).join('')}</div>${detailTab==='material'?'<section id="filePanel" class="card"><p class="muted">Cargando materiales...</p></section>':detailTab==='notes'?noteCard('class:'+c.id):detailTab==='ai'?aiPanel(c):classCards(c)}`}
function settings(){view.innerHTML=`<section class="card"><h2>Personalización</h2><p class="muted">Elige un tema. Se aplica de inmediato y queda guardado en este iPhone.</p><div class="theme-grid" role="group" aria-label="Color de la aplicación">${[['rose','Rosa pastel','#C46C91'],['lavender','Lavanda','#8B6BB3'],['sage','Verde salvia','#608C77'],['sky','Azul cielo','#518CC7'],['dark','Oscuro','#B19AE7']].map(([id,name,color])=>`<button type="button" class="theme-choice ${getTheme()===id?'selected':''}" data-theme-choice="${id}" aria-pressed="${getTheme()===id}"><span class="theme-dot" style="background:${color}"></span>${name}</button>`).join('')}</div></section><section class="card"><h2>Datos y respaldos</h2><p class="muted">La información de esta aplicación se guarda automáticamente en este navegador mediante IndexedDB.</p><div class="buttonrow"><button class="btn" data-action="export">Exportar JSON</button><button class="btn secondary" data-action="import">Importar JSON</button></div><input id="importFile" type="file" accept="application/json,.json" hidden><p class="notice warning">El almacenamiento local puede borrarse al limpiar los datos del navegador. Guarda respaldos periódicos en Archivos o iCloud Drive. Los respaldos de esta versión contienen unidades, clases y etiquetas; los archivos adjuntos NO están incluidos en el JSON; los resúmenes y mapas importados SÍ están incluidos; la agenda, las flashcards y sus repasos sí. Conserva los originales hasta incorporar un respaldo completo.</p></section><section class="card"><h2>Acerca de la versión</h2><p class="muted">Versión 0.5 · Estudio asistido, agenda académica y flashcards y repetición espaciada, editor y documentos.</p><p class="muted">Para instalarla en el iPhone como PWA, hay que publicar la carpeta en un alojamiento HTTPS. Abrir index.html directamente sirve para una vista preliminar, pero puede restringir el almacenamiento o las funciones sin conexión.</p></section>`;$('#importFile').addEventListener('change',importFile)}
function openForm(mode,id){dialogMode=mode;editingId=mode.startsWith('edit')?id:null;const unit=mode==='edit-unit'?data.units.find(x=>x.id===id):null, cls=mode==='edit-class'?data.classes.find(x=>x.id===id):null;$('#formTitle').textContent=mode.includes('unit')?(unit?'Editar unidad':'Nueva unidad'):(cls?'Editar clase':'Nueva clase');$('#nameLabel').firstChild.textContent=mode.includes('unit')?'Nombre de la unidad':'Título de la clase';$('#entityName').value=unit?.title||cls?.title||'';$('#unitField').hidden=mode.includes('unit');$('#dateField').hidden=mode.includes('unit');$('#tagsField').hidden=mode.includes('unit');$('#entityUnit').innerHTML=data.units.map(u=>`<option value="${esc(u.id)}">${esc(u.title)}</option>`).join('');if(cls)$('#entityUnit').value=cls.unitId;else if(id&&mode==='new-class')$('#entityUnit').value=id;$('#entityDate').value=cls?.date||'';$('#entityTags').value=cls?.tags?.join(', ')||'';$('#editorDialog').showModal();$('#entityName').focus()}
async function submitForm(){const title=$('#entityName').value.trim();if(!title){showToast('Escribe un nombre');return}if(dialogMode.includes('unit')){if(editingId){data.units.find(u=>u.id===editingId).title=title}else{const unit={id:uid(),title,createdAt:new Date().toISOString()};data.units.push(unit);activeUnit=unit.id}}else{const unitId=$('#entityUnit').value;if(!data.units.some(u=>u.id===unitId)){showToast('Selecciona una unidad');return}const tags=[...new Set($('#entityTags').value.split(',').map(t=>t.trim()).filter(Boolean))];const now=new Date().toISOString();if(editingId){Object.assign(data.classes.find(c=>c.id===editingId),{title,unitId,date:$('#entityDate').value,tags,updatedAt:now})}else{const c={id:uid(),title,unitId,date:$('#entityDate').value,tags,createdAt:now,updatedAt:now};data.classes.push(c);activeClass=c.id}}await save();$('#editorDialog').close();showToast('Guardado correctamente');if(dialogMode==='new-unit')navigate('unit');else if(dialogMode==='new-class')navigate('detail');else render()}
async function removeUnit(id){const u=data.units.find(x=>x.id===id);if(!u||!confirm(`¿Eliminar "${u.title}" y todas sus clases? Esta acción no se puede deshacer.`))return;data.cards=data.cards.filter(c=>!data.classes.some(x=>x.unitId===id&&x.id===c.classId));data.aiDocuments=(data.aiDocuments||[]).filter(x=>!data.classes.some(c=>c.unitId===id&&c.id===x.classId));data.agenda=(data.agenda||[]).map(x=>x.unitId===id?{...x,unitId:'',classId:''}:x);data.units=data.units.filter(x=>x.id!==id);data.classes=data.classes.filter(c=>c.unitId!==id);delete data.notes['unit:'+id];await purgeAttachments(c=>c.unitId===id);await save();showToast('Unidad eliminada');navigate('classes')}
async function removeClass(id){const c=data.classes.find(x=>x.id===id);if(!c||!confirm(`¿Eliminar la clase "${c.title}"? Esta acción no se puede deshacer.`))return;data.cards=data.cards.filter(x=>x.classId!==id);data.aiDocuments=(data.aiDocuments||[]).filter(x=>x.classId!==id);data.agenda=(data.agenda||[]).map(x=>x.classId===id?{...x,classId:''}:x);data.classes=data.classes.filter(x=>x.id!==id);delete data.notes['class:'+id];await purgeAttachments(f=>f.classId===id);await save();showToast('Clase eliminada');activeUnit=c.unitId;navigate('unit')}
function exportFile(){const contents=JSON.stringify({format:'espacio-estudio',version:5,exportedAt:new Date().toISOString(),data},null,2);const url=URL.createObjectURL(new Blob([contents],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`respaldo-estudio-${new Date().toISOString().slice(0,10)}.json`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);showToast('Respaldo preparado')}
async function importFile(e){const file=e.target.files[0];if(!file)return;try{const obj=JSON.parse(await file.text());if(obj.format!=='espacio-estudio'||!Array.isArray(obj.data?.units)||!Array.isArray(obj.data?.classes))throw Error('Formato de respaldo no válido');const ids=new Set(obj.data.units.map(x=>x.id));if(obj.data.units.some(u=>typeof u.id!=='string'||typeof u.title!=='string')||obj.data.classes.some(c=>typeof c.id!=='string'||typeof c.title!=='string'||!ids.has(c.unitId)||!Array.isArray(c.tags)||c.tags.some(t=>typeof t!=='string')))throw Error('Datos de respaldo incompletos');if(!confirm('¿Reemplazar todas las unidades y clases actuales por el contenido del respaldo?'))return;data={notes:typeof obj.data.notes==='object'&&obj.data.notes&&!Array.isArray(obj.data.notes)?obj.data.notes:{},units:obj.data.units.map(u=>({id:u.id,title:u.title,createdAt:u.createdAt||''})),classes:obj.data.classes.map(c=>({id:c.id,title:c.title,unitId:c.unitId,date:c.date||'',tags:c.tags,createdAt:c.createdAt||'',updatedAt:c.updatedAt||''})),cards:Array.isArray(obj.data.cards)?obj.data.cards.filter(validCard):[],agenda:Array.isArray(obj.data.agenda)?obj.data.agenda.filter(validAgendaItem):[],aiDocuments:Array.isArray(obj.data.aiDocuments)?obj.data.aiDocuments.filter(validAIDocument):[]};await save();searchText='';tagFilter='';navigate('classes');showToast('Respaldo restaurado')}catch(err){alert('No fue posible importar: '+err.message)}finally{e.target.value=''}}
const THEME_KEY='espacio-estudio-tema';
const VALID_THEMES=['rose','lavender','sage','sky','dark'];
function getTheme(){try{const v=localStorage.getItem(THEME_KEY);return VALID_THEMES.includes(v)?v:'rose'}catch{return 'rose'}}
function applyTheme(theme){if(!VALID_THEMES.includes(theme))return;document.documentElement.dataset.theme=theme;try{localStorage.setItem(THEME_KEY,theme)}catch{};document.querySelector('meta[name="theme-color"]')?.setAttribute('content',theme==='dark'?'#1B1D29':({rose:'#FFF6F8',lavender:'#F8F5FC',sage:'#F4F8F3',sky:'#F3F8FE'})[theme]);document.querySelectorAll('[data-theme-choice]').forEach(b=>{const yes=b.dataset.themeChoice===theme;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))})}
applyTheme(getTheme());
view.addEventListener('click',async e=>{const themeButton=e.target.closest('[data-theme-choice]');if(themeButton){applyTheme(themeButton.dataset.themeChoice);showToast('Tema actualizado');return;}const tag=e.target.closest('[data-tag]');if(tag){tagFilter=tag.dataset.tag;classes();return}const tab=e.target.closest('[data-tab]');if(tab){detailTab=tab.dataset.tab;render();return}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=b.dataset.id;if(action==='ai-prepare')openAIRequest();else if(action==='ai-import')openAIImport();else if(action==='ai-open')openAIResult(id);else if(action==='ai-delete')await deleteAIResult(id);else if(action==='edit-note')openNote(b.dataset.note);else if(action==='attach')$('#attachInput').click();else if(action==='remove-attachment')await removeAttachment(id);else if(action==='view-attachment')await showAttachment(id);else if(action==='go-classes')navigate('classes');else if(action==='go-study')navigate('study');else if(action==='go-agenda')navigate('agenda');else if(action==='new-card')openCardForm(null,id||activeClass);else if(action==='edit-card')openCardForm(id);else if(action==='schedule-card')openScheduleDialog(id);else if(action==='delete-card')await deleteCard(id);else if(action==='start-review')startReview(b.dataset.scope||'all',id||'');else if(action==='show-answer')showAnswer();else if(action==='rate-card')await rateCard(b.dataset.rating);else if(action==='end-review')endReview();else if(action==='new-unit')openForm('new-unit');else if(action==='edit-unit')openForm('edit-unit',id);else if(action==='new-class')openForm('new-class',id);else if(action==='edit-class')openForm('edit-class',id);else if(action==='open-unit'){activeUnit=id;navigate('unit')}else if(action==='open-class'){activeClass=id;detailTab='material';navigate('detail')}else if(action==='delete-unit')await removeUnit(id);else if(action==='delete-class')await removeClass(id);else if(action==='export')exportFile();else if(action==='import')$('#importFile').click();});
// Deletion uses long-press-safe explicit controls within edit dialog.
$('#entityForm').addEventListener('submit',e=>{e.preventDefault();submitForm().catch(err=>alert('Error al guardar: '+err.message))});$('#cancelForm').addEventListener('click',()=>$('#editorDialog').close());$('#settingsBtn').addEventListener('click',()=>navigate('settings'));document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.nav)));

// v0.3 Tarjetas y repetición espaciada. Todos los registros permanecen en STORE/data.
function validCard(c){return !!(c&&typeof c.id==='string'&&typeof c.classId==='string'&&typeof c.front==='string'&&typeof c.back==='string'&&c.front.trim()&&c.back.trim());}
const dayMS=86400000;
function localDay(t=Date.now()){const d=new Date(t);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function addDays(days){const d=new Date();d.setHours(12,0,0,0);d.setDate(d.getDate()+days);return localDay(d.getTime());}
function dueCards(list=data.cards){const day=localDay();return list.filter(c=>!c.due||c.due<=day);}
function cardUnit(c){return data.classes.find(x=>x.id===c.classId)?.unitId;}
function classCards(cls){const cards=data.cards.filter(c=>c.classId===cls.id);return `<section class="card"><div class="row"><h2>Flashcards</h2><button class="btn small" data-action="new-card" data-id="${esc(cls.id)}">+ Tarjeta</button></div><p class="muted">${cards.length} tarjetas · ${dueCards(cards).length} pendientes</p>${cards.map(c=>`<div class="listitem"><div class="titleline">${esc(c.front)}</div><p class="muted">${esc(c.back)}</p><p class="muted card-next-date">Próximo repaso: ${esc(c.due||localDay())} · ${c.scheduleMode==='manual'?'Fecha personalizada':'Automático'}</p><div class="buttonrow"><button class="btn secondary small" data-action="edit-card" data-id="${esc(c.id)}">Editar</button><button class="btn secondary small" data-action="schedule-card" data-id="${esc(c.id)}">Programar</button><button class="btn danger small" data-action="delete-card" data-id="${esc(c.id)}">Eliminar</button></div></div>`).join('')||'<p class="muted">Crea tu primera pregunta y respuesta.</p>'}<button class="btn secondary" data-action="start-review" data-scope="class" data-id="${esc(cls.id)}" ${!dueCards(cards).length?'disabled':''}>Repasar pendientes de esta clase</button></section>`;}
function studyView(){const total=data.cards.length,due=dueCards();view.innerHTML=`<section class="card hero"><span class="eyebrow">REPASO DE HOY</span><h2>${due.length} tarjetas pendientes</h2><p class="muted">${total} tarjetas creadas · ${total-due.length} programadas para más adelante</p><button class="btn" data-action="start-review" data-scope="all" ${!due.length?'disabled':''}>Empezar repaso</button></section><section class="card"><h2>Estudiar por unidad</h2>${data.units.map(u=>{const cards=data.cards.filter(c=>cardUnit(c)===u.id);return `<div class="listitem"><div class="row"><div><b>${esc(u.title)}</b><p class="muted">${dueCards(cards).length} pendientes de ${cards.length}</p></div><button class="btn secondary small" data-action="start-review" data-scope="unit" data-id="${esc(u.id)}" ${!dueCards(cards).length?'disabled':''}>Repasar</button></div></div>`}).join('')||'<p class="muted">Primero crea una unidad y tarjetas en sus clases.</p>'}</section><section class="card"><h2>Próximos repasos</h2><p class="muted">${data.cards.filter(c=>c.due&&c.due>localDay()).slice().sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5).map(c=>esc(c.due)+' · '+esc(c.front)).join('<br>')||'Todavía no hay repasos futuros.'}</p></section>`;}
let editingCardId=null,reviewSession=null;
function openCardForm(id=null,classId=null){const c=id?data.cards.find(c=>c.id===id):null;editingCardId=id;const select=$('#cardClass');select.innerHTML=data.classes.map(cls=>`<option value="${esc(cls.id)}">${esc(data.units.find(u=>u.id===cls.unitId)?.title||'Unidad')} · ${esc(cls.title)}</option>`).join('');if(c||classId)select.value=c?.classId||classId;$('#cardFront').value=c?.front||'';$('#cardBack').value=c?.back||'';$('#cardDialogTitle').textContent=c?'Editar tarjeta':'Nueva tarjeta';$('#cardDialog').showModal();}
$('#cardCancel').addEventListener('click',()=>$('#cardDialog').close());

// v0.3.1: la fecha manual sustituye solo el próximo vencimiento. No borra reseñas ni intervalos.
let schedulingCardId=null;
function openScheduleDialog(id){
  const c=data.cards.find(x=>x.id===id);if(!c)return;
  schedulingCardId=id;
  $('#scheduleCardName').textContent=c.front;
  $('#scheduleAutoDue').textContent=c.autoDue||c.due||localDay();
  const manual=c.scheduleMode==='manual';
  $('#scheduleModeAuto').checked=!manual;
  $('#scheduleModeManual').checked=manual;
  $('#scheduleDate').min=localDay();
  $('#scheduleDate').value=manual&&c.due?c.due:(c.autoDue||c.due||localDay());
  if($('#scheduleDate').value<localDay())$('#scheduleDate').value=localDay();
  updateScheduleControl();
  $('#scheduleDialog').showModal();
}
function updateScheduleControl(){const manual=$('#scheduleModeManual').checked;$('#scheduleDateArea').hidden=!manual;$('#scheduleDate').required=manual;}
$('#scheduleModeAuto').addEventListener('change',updateScheduleControl);
$('#scheduleModeManual').addEventListener('change',updateScheduleControl);
$('#scheduleCancel').addEventListener('click',()=>$('#scheduleDialog').close());
function validScheduleDate(v){if(!/^\d{4}-\d{2}-\d{2}$/.test(v))return false;const d=new Date(v+'T12:00:00');return !Number.isNaN(d.getTime())&&localDay(d.getTime())===v&&v>=localDay();}
$('#scheduleForm').addEventListener('submit',async e=>{
  e.preventDefault();
  const c=data.cards.find(x=>x.id===schedulingCardId);if(!c)return;
  const manual=$('#scheduleModeManual').checked;
  const chosen=$('#scheduleDate').value;
  if(manual&&!validScheduleDate(chosen)){alert('Selecciona una fecha válida, desde hoy en adelante.');return;}
  const before=JSON.stringify(c);
  try{
    if(manual){c.autoDue=c.autoDue||c.due||localDay();c.due=chosen;c.scheduleMode='manual';}
    else{c.due=c.autoDue||c.due||localDay();c.autoDue=c.due;c.scheduleMode='auto';}
    await save();
    $('#scheduleDialog').close();render();showToast('Próximo repaso actualizado');
  }catch(err){Object.assign(c,JSON.parse(before));alert('No se guardó la fecha: '+err.message);}
});

$('#cardForm').addEventListener('submit',async e=>{e.preventDefault();const front=$('#cardFront').value.trim(),back=$('#cardBack').value.trim(),classId=$('#cardClass').value;if(!front||!back||!data.classes.some(c=>c.id===classId))return;const previous=editingCardId?data.cards.find(c=>c.id===editingCardId):null;const snapshot=JSON.stringify(data.cards);try{if(previous)Object.assign(previous,{front,back,classId});else data.cards.push({id:uid(),classId,front,back,due:localDay(),autoDue:localDay(),scheduleMode:'auto',interval:0,ease:2.5,repetitions:0,reviews:[]});await save();$('#cardDialog').close();render();showToast('Tarjeta guardada')}catch(err){data.cards=JSON.parse(snapshot);alert('No se guardó la tarjeta: '+err.message)}});
async function deleteCard(id){const c=data.cards.find(c=>c.id===id);if(!c||!confirm('¿Eliminar esta tarjeta y su historial de repaso?'))return;const before=data.cards.slice();data.cards=data.cards.filter(c=>c.id!==id);try{await save();render()}catch(e){data.cards=before;alert('Error al eliminar: '+e.message)}}
function startReview(scope,id){let arr=data.cards.filter(c=>scope==='all'||scope==='class'&&c.classId===id||scope==='unit'&&cardUnit(c)===id);arr=dueCards(arr);if(!arr.length){showToast('No hay tarjetas pendientes');return;}reviewSession={ids:arr.map(c=>c.id),position:0,shown:false,completed:0};navigate('study');}
function renderReview(){const r=reviewSession;if(!r)return studyView();const id=r.ids[r.position],c=data.cards.find(x=>x.id===id);if(!c){r.position++;if(r.position>=r.ids.length)return endReview();return renderReview();}view.innerHTML=`<section class="card"><div class="row"><h2>Sesión de repaso</h2><button class="btn ghost small" data-action="end-review">Terminar</button></div><p class="muted">Tarjeta ${r.position+1} de ${r.ids.length}</p><div class="review-question"><span class="eyebrow">${r.shown?'RESPUESTA':'PREGUNTA'}</span><h2>${esc(r.shown?c.back:c.front)}</h2></div>${!r.shown?'<button class="btn review-wide" data-action="show-answer">Mostrar respuesta</button>':`<p class="muted">¿Cómo recordaste la respuesta?</p><div class="rating-grid"><button class="btn danger" data-action="rate-card" data-rating="again">Otra vez</button><button class="btn secondary" data-action="rate-card" data-rating="hard">Difícil</button><button class="btn secondary" data-action="rate-card" data-rating="good">Bien</button><button class="btn secondary" data-action="rate-card" data-rating="easy">Fácil</button></div>`}</section>`;}
function showAnswer(){if(reviewSession){reviewSession.shown=true;renderReview();}}
// Algoritmo sencillo de intervalos progresivos, no FSRS. Una respuesta «Otra vez» queda para el día siguiente.
function scheduleCard(card,rating){const old=card.interval||0;let days=1;let ease=card.ease||2.5;let reps=card.repetitions||0;if(rating==='again'){days=1;reps=0;ease=Math.max(1.3,ease-.2)}else if(rating==='hard'){days=Math.max(1,Math.round(old?old*1.2:1));ease=Math.max(1.3,ease-.15);reps++}else if(rating==='good'){days=old?Math.max(old+1,Math.round(old*ease)):2;reps++}else{days=old?Math.max(old+2,Math.round(old*ease*1.3)):4;ease=Math.min(3.2,ease+.15);reps++}card.interval=days;card.ease=ease;card.repetitions=reps;card.due=addDays(days);card.autoDue=card.due;card.scheduleMode='auto';card.reviews=Array.isArray(card.reviews)?card.reviews:[];card.reviews.push({at:new Date().toISOString(),rating,days,due:card.due});}
async function rateCard(rating){if(!reviewSession||!['again','hard','good','easy'].includes(rating))return;const c=data.cards.find(x=>x.id===reviewSession.ids[reviewSession.position]);if(!c)return;const old=JSON.stringify(c);scheduleCard(c,rating);try{await save();reviewSession.completed++;reviewSession.position++;reviewSession.shown=false;if(reviewSession.position>=reviewSession.ids.length){const n=reviewSession.completed;reviewSession=null;studyView();showToast(`Sesión terminada: ${n} tarjetas guardadas`);}else renderReview();}catch(e){Object.assign(c,JSON.parse(old));alert('No se guardó el repaso. Inténtalo de nuevo: '+e.message)}}
function endReview(){reviewSession=null;studyView();}

(async()=>{try{db=await openDB();data=await readData();data.notes ||= {};data.cards=Array.isArray(data.cards)?data.cards.filter(validCard):[];data.aiDocuments=Array.isArray(data.aiDocuments)?data.aiDocuments.filter(validAIDocument):[];if(!Array.isArray(data.units)||!Array.isArray(data.classes))throw Error('Datos inválidos');render();if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js').catch(()=>{})}catch(err){view.innerHTML=`<div class="card"><h2>No se pudo abrir el almacenamiento local</h2><p class="muted">${esc(err.message)}. Intenta abrir la aplicación desde un sitio HTTPS, no desde un archivo local.</p></div>`}})();


// Bloque 2: editor local y documentos. Mantiene la misma clave de datos de v0.1.
function noteCard(key){const html=data.notes?.[key]||'';return `<section class="card"><div class="row"><div><h2>Apuntes</h2><p class="muted">Se guardan automáticamente</p></div><button class="btn" data-action="edit-note" data-note="${esc(key)}">Editar</button></div><div class="note-preview">${sanitizeNote(html)||'<p class="muted">Todavía no hay apuntes. Pulsa Editar para comenzar.</p>'}</div></section>`}
function sanitizeNote(input){const doc=new DOMParser().parseFromString(String(input||''),'text/html');const allowed=new Set(['P','H2','H3','BR','B','I','U','STRONG','EM','UL','OL','LI','BLOCKQUOTE','TABLE','TBODY','THEAD','TR','TD','TH','SPAN','DIV','IMG']);function clean(node){for(const child of [...node.childNodes]){if(child.nodeType===8){child.remove();continue}if(child.nodeType!==1)continue;if(!allowed.has(child.tagName)){const text=doc.createTextNode(child.textContent||'');child.replaceWith(text);continue}for(const a of [...child.attributes]){const permitted=child.tagName==='IMG'&&a.name==='src'&&/^data:image\/(png|jpeg|webp|gif);base64,/i.test(a.value)&&a.value.length<2200000 || a.name==='style'&&/^(color|background-color):\s*(#[0-9a-f]{3,8}|rgb\([\d ,.%]+\));?$/i.test(a.value);if(!permitted)child.removeAttribute(a.name)}clean(child)}}clean(doc.body);return doc.body.innerHTML}
let activeNoteKey='', noteTimer=null, noteRevision=0, noteSaving=Promise.resolve();
function openNote(key){activeNoteKey=key;noteRevision=0;clearTimeout(noteTimer);const label=key.startsWith('unit:')?'Resumen de unidad':'Apuntes de clase';$('#noteTitle').textContent=label;$('#noteEditor').innerHTML=sanitizeNote(data.notes?.[key]||'');$('#noteStatus').textContent='Sin cambios';$('#noteDialog').showModal()}
function captureNote(){if(!activeNoteKey)return null;return {key:activeNoteKey,html:sanitizeNote($('#noteEditor').innerHTML),rev:noteRevision}}
async function persistNote(){const snap=captureNote();if(!snap)return;data.notes[snap.key]=snap.html;noteSaving=noteSaving.catch(()=>{}).then(async()=>{const tx=db.transaction(STORE,'readwrite');await new Promise((resolve,reject)=>{tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error||new Error('Error de almacenamiento'));tx.onabort=()=>reject(tx.error||new Error('Escritura cancelada'));tx.objectStore(STORE).put(data,'data')});const stored=await request(db.transaction(STORE,'readonly').objectStore(STORE).get('data'));if(stored?.notes?.[snap.key]!==snap.html)throw new Error('La verificación del guardado falló');if(snap.key===activeNoteKey&&snap.rev===noteRevision)$('#noteStatus').textContent='Guardado y comprobado'});return noteSaving}
$('#noteEditor').addEventListener('input',()=>{noteRevision++;$('#noteStatus').textContent='Cambios pendientes…';clearTimeout(noteTimer);noteTimer=setTimeout(()=>persistNote().catch(e=>{$('#noteStatus').textContent='No se guardó: '+e.message}),900)});
$('#closeNote').addEventListener('click',async()=>{clearTimeout(noteTimer);$('#closeNote').disabled=true;$('#noteStatus').textContent='Comprobando guardado…';try{await noteSaving.catch(()=>{});await persistNote();$('#noteDialog').close();activeNoteKey='';render();showToast('Apuntes guardados y comprobados')}catch(e){$('#noteStatus').textContent='Error: '+e.message;alert('No se pudieron guardar los apuntes. Mantén abierto el editor para no perderlos. Detalle: '+e.message)}finally{$('#closeNote').disabled=false}});
$('#noteTools').addEventListener('click',e=>{const b=e.target.closest('[data-command]');if(!b)return;$('#noteEditor').focus();const cmd=b.dataset.command;if(cmd==='insertTable'){document.execCommand('insertHTML',false,'<table><tbody><tr><td>Celda</td><td>Celda</td></tr><tr><td>Celda</td><td>Celda</td></tr></tbody></table>')}else if(cmd==='foreColor'||cmd==='hiliteColor'){document.execCommand(cmd,false,b.dataset.value)}else if(cmd==='formatBlock'){document.execCommand(cmd,false,b.dataset.value)}else document.execCommand(cmd,false,null);$('#noteEditor').dispatchEvent(new Event('input'))});
$('#noteImageBtn').addEventListener('click',()=>$('#noteImageInput').click());
$('#noteImageInput').addEventListener('change',async e=>{const f=e.target.files?.[0];if(!f)return;if(f.size>1400000){alert('La imagen debe pesar menos de 1,4 MB para incorporarla al apunte. Puedes adjuntarla como material si es más grande.');return}const reader=new FileReader();reader.onload=()=>{$('#noteEditor').focus();document.execCommand('insertImage',false,reader.result);$('#noteEditor').dispatchEvent(new Event('input'))};reader.readAsDataURL(f);e.target.value=''});
function filesStore(mode){return db.transaction(FILE_STORE,mode).objectStore(FILE_STORE)}
async function listFiles(){const items=await request(filesStore('readonly').getAll());return items.filter(x=>x.classId===activeClass)}
async function loadAttachments(){const el=$('#filePanel');if(!el)return;try{const files=await listFiles();el.innerHTML=`<h2>Materiales de clase</h2><p class="muted">PDF e imágenes disponibles dentro y fuera de la aplicación. Las presentaciones deben exportarse a PDF.</p><button class="btn" data-action="attach">+ Adjuntar archivo</button>${files.length?files.map(x=>`<div class="listitem"><div class="titleline">${esc(x.name)}</div><p class="muted">${(x.blob.size/1048576).toFixed(1)} MB</p><div class="buttonrow"><button class="btn secondary small" data-action="view-attachment" data-id="${esc(x.id)}">Ver archivo</button><button class="btn danger small" data-action="remove-attachment" data-id="${esc(x.id)}">Eliminar</button></div></div>`).join(''):'<p class="muted">Todavía no tienes archivos adjuntos.</p>'}</section>`}catch(e){el.textContent='Error al abrir archivos: '+e.message}}
$('#attachInput').addEventListener('change',async e=>{const files=[...e.target.files];for(const file of files){if(!(['application/pdf','image/jpeg','image/png','image/webp','image/gif'].includes(file.type))){alert('Formato no admitido: '+file.name+'. Convierte presentaciones a PDF.');continue}try{await request(filesStore('readwrite').put({id:uid(),classId:activeClass,unitId:data.classes.find(c=>c.id===activeClass)?.unitId,name:file.name,type:file.type,blob:file,addedAt:new Date().toISOString()}))}catch(err){alert('No se pudo guardar '+file.name+': '+err.message)}}e.target.value='';loadAttachments()});
// v0.2.4: visor PDF.js, una página a la vez, sin depender del iframe nativo de Safari.
const PDFJS_URL='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js';
const PDF_WORKER_URL='https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
let pdfScriptPromise=null, activePdfSession=null;
function loadPdfEngine(){
  if(window.pdfjsLib)return Promise.resolve(window.pdfjsLib);
  if(!pdfScriptPromise)pdfScriptPromise=new Promise((resolve,reject)=>{
    const script=document.createElement('script');script.src=PDFJS_URL;script.async=true;
    script.onload=()=>window.pdfjsLib?resolve(window.pdfjsLib):reject(new Error('Biblioteca PDF no disponible'));
    script.onerror=()=>reject(new Error('No se pudo descargar el lector PDF. Comprueba tu conexión a internet.'));
    document.head.appendChild(script);
  }).catch(error=>{pdfScriptPromise=null;throw error});
  return pdfScriptPromise;
}
async function showAttachment(id){
  const file=await request(filesStore('readonly').get(id));if(!file)return;
  if(activePdfSession)activePdfSession.closed=true;
  const url=URL.createObjectURL(file.blob),body=$('#fileBody'),isPdf=file.type==='application/pdf';
  $('#fileTitle').textContent=file.name;body.replaceChildren();
  $('#fileControls').hidden=true;
  const external=$('#openFileExternal');external.href=url;external.target='_blank';
  $('#fileDialog').showModal();
  const session={closed:false,url,doc:null,page:1,zoom:1,rendering:false};activePdfSession=session;
  const close=()=>{
    session.closed=true;if(session.doc)session.doc.destroy().catch(()=>{});
    body.replaceChildren();$('#fileDialog').close();
    setTimeout(()=>URL.revokeObjectURL(url),60000);
  };
  $('#closeFile').onclick=close;
  if(!isPdf){
    const img=document.createElement('img');img.src=url;img.className='file-preview image-preview';img.alt=file.name;body.append(img);return;
  }
  body.innerHTML='<p class="hint pdf-loading" role="status">Preparando lector PDF…</p>';
  try{
    const lib=await loadPdfEngine();if(session.closed)return;
    lib.GlobalWorkerOptions.workerSrc=PDF_WORKER_URL;
    const buffer=await file.blob.arrayBuffer();if(session.closed)return;
    session.doc=await lib.getDocument({data:new Uint8Array(buffer)}).promise;
    if(session.closed)return;
    const wrapper=document.createElement('div');wrapper.className='pdfjs-reader';
    wrapper.innerHTML=`<div class="pdfjs-toolbar"><button class="btn secondary small" data-pdf="prev" type="button">Anterior</button><span data-pdf="counter" aria-live="polite"></span><button class="btn secondary small" data-pdf="next" type="button">Siguiente</button></div><div class="pdfjs-toolbar"><button class="btn secondary small" type="button" data-pdf="out">−</button><button class="btn secondary small" type="button" data-pdf="reset">Ajustar</button><button class="btn secondary small" type="button" data-pdf="in">+</button></div><div class="pdfjs-scroll"><canvas aria-label="Página del documento PDF"></canvas></div><p class="hint">Desliza horizontalmente si amplías la página. También puedes abrir el archivo fuera de Estudio.</p>`;
    body.replaceChildren(wrapper);
    const canvas=wrapper.querySelector('canvas'),scroller=wrapper.querySelector('.pdfjs-scroll');
    let pending=false;
    async function renderPage(){
      if(session.closed)return;
      if(session.rendering){pending=true;return;}
      session.rendering=true;
      try{
        const page=await session.doc.getPage(session.page);if(session.closed)return;
        const base=page.getViewport({scale:1});
        const available=Math.max(260,scroller.clientWidth-4);
        const scale=available/base.width*session.zoom;
        const viewport=page.getViewport({scale});
        const pixelRatio=Math.min(window.devicePixelRatio||1,2);
        canvas.width=Math.round(viewport.width*pixelRatio);canvas.height=Math.round(viewport.height*pixelRatio);
        canvas.style.width=viewport.width+'px';canvas.style.height=viewport.height+'px';
        await page.render({canvasContext:canvas.getContext('2d'),viewport,transform:pixelRatio===1?null:[pixelRatio,0,0,pixelRatio,0,0]}).promise;
        if(session.closed)return;
        wrapper.querySelector('[data-pdf="counter"]').textContent=`${session.page} / ${session.doc.numPages}`;
        wrapper.querySelector('[data-pdf="prev"]').disabled=session.page===1;
        wrapper.querySelector('[data-pdf="next"]').disabled=session.page===session.doc.numPages;
        scroller.scrollLeft=0;scroller.scrollTop=0;
      }catch(e){if(!session.closed)wrapper.insertAdjacentHTML('beforeend','<p class="hint">No se pudo representar esta página. Usa «Abrir fuera de la aplicación».</p>');}
      finally{session.rendering=false;if(pending&&!session.closed){pending=false;renderPage()}}
    }
    wrapper.addEventListener('click',event=>{
      const button=event.target.closest('[data-pdf]');if(!button)return;
      switch(button.dataset.pdf){
        case 'prev':session.page=Math.max(1,session.page-1);break;
        case 'next':session.page=Math.min(session.doc.numPages,session.page+1);break;
        case 'out':session.zoom=Math.max(0.75,+(session.zoom-0.25).toFixed(2));break;
        case 'in':session.zoom=Math.min(3,+(session.zoom+0.25).toFixed(2));break;
        case 'reset':session.zoom=1;break;
      }
      renderPage();
    });
    await renderPage();
  }catch(error){if(!session.closed){body.replaceChildren();const msg=document.createElement('p');msg.className='hint';msg.textContent='No se pudo cargar el visor integrado: '+error.message+' Puedes abrir el PDF fuera de Estudio.';body.append(msg)}}
}
async function removeAttachment(id){if(!confirm('¿Eliminar este archivo adjunto?'))return;await request(filesStore('readwrite').delete(id));loadAttachments()}
async function purgeAttachments(predicate){const all=await request(filesStore('readonly').getAll());for(const x of all.filter(predicate))await request(filesStore('readwrite').delete(x.id))}

