// v0.4 Agenda académica: los registros viven en records/data y se incluyen en JSON.
let editingAgendaId=null, agendaFilter='pending';
function validAgendaItem(x){return !!(x&&typeof x.id==='string'&&typeof x.title==='string'&&x.title.trim()&&/^\d{4}-\d{2}-\d{2}$/.test(x.date)&&['evaluacion','entrega','tarea'].includes(x.kind));}
function agendaSort(a,b){return (a.done===b.done?0:a.done?1:-1)||(a.date||'').localeCompare(b.date||'')||a.title.localeCompare(b.title,'es');}
function agendaView(){
  data.agenda ||= [];
  const pending=data.agenda.filter(x=>!x.done), finished=data.agenda.filter(x=>x.done);
  const list=(agendaFilter==='pending'?pending:agendaFilter==='completed'?finished:data.agenda).slice().sort(agendaSort);
  const kindName={evaluacion:'Evaluación',entrega:'Entrega',tarea:'Tarea'};
  view.innerHTML=`<section class="card"><div class="row"><div><h2>Agenda académica</h2><p class="muted">Pruebas, entregas y tareas de tu asignatura.</p></div><button class="btn small" data-agenda="new">+ Añadir</button></div><div class="agenda-stats"><span><strong>${pending.length}</strong> pendientes</span><span><strong>${finished.length}</strong> completadas</span></div><div class="agenda-filters"><button class="btn ${agendaFilter==='pending'?'':'secondary'} small" data-agenda="filter" data-filter="pending">Pendientes</button><button class="btn ${agendaFilter==='all'?'':'secondary'} small" data-agenda="filter" data-filter="all">Todas</button><button class="btn ${agendaFilter==='completed'?'':'secondary'} small" data-agenda="filter" data-filter="completed">Completadas</button></div></section><section class="card agenda-list">${list.length?list.map(x=>{
    const u=data.units.find(u=>u.id===x.unitId),c=data.classes.find(c=>c.id===x.classId);
    const overdue=!x.done&&x.date<localDay();
    return `<article class="agenda-item ${x.done?'agenda-done':''}"><div class="agenda-item-header"><div><span class="agenda-kind">${kindName[x.kind]}</span> <span class="agenda-date ${overdue?'agenda-late':''}">${esc(x.date)}${overdue?' · Atrasada':''}</span><h3>${esc(x.title)}</h3>${u||c?`<p class="muted">${esc([u?.title,c?.title].filter(Boolean).join(' · '))}</p>`:''}${x.notes?`<p class="agenda-notes">${esc(x.notes)}</p>`:''}</div></div><div class="agenda-actions"><button class="btn secondary small" data-agenda="toggle" data-id="${esc(x.id)}">${x.done?'Reabrir':'Completar'}</button><button class="btn secondary small" data-agenda="edit" data-id="${esc(x.id)}">Editar</button><button class="btn danger small" data-agenda="remove" data-id="${esc(x.id)}">Eliminar</button></div></article>`}).join(''):'<p class="muted">No hay actividades en esta vista. Pulsa «Añadir» para crear una.</p>'}</section>`;
}
function fillAgendaUnits(unitId='',classId=''){
 const u=$('#agendaUnit'), c=$('#agendaClass');
 u.innerHTML='<option value="">Sin unidad</option>'+data.units.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');
 u.value=unitId;
 const classes=data.classes.filter(x=>!u.value||x.unitId===u.value);
 c.innerHTML='<option value="">Sin clase</option>'+classes.map(x=>`<option value="${esc(x.id)}">${esc(x.title)}</option>`).join('');
 c.value=classId;
}
function openAgendaForm(id=null){
 const x=id?(data.agenda||[]).find(a=>a.id===id):null; editingAgendaId=x?.id||null;
 $('#agendaFormTitle').textContent=x?'Editar actividad':'Nueva actividad';
 $('#agendaKind').value=x?.kind||'tarea';$('#agendaTitle').value=x?.title||'';
 $('#agendaDate').value=x?.date||localDay();$('#agendaNotes').value=x?.notes||'';
 fillAgendaUnits(x?.unitId||'',x?.classId||'');$('#agendaDialog').showModal();
}
$('#agendaUnit').addEventListener('change',()=>fillAgendaUnits($('#agendaUnit').value));
$('#agendaCancel').addEventListener('click',()=>$('#agendaDialog').close());
$('#agendaForm').addEventListener('submit',async e=>{
 e.preventDefault();const title=$('#agendaTitle').value.trim(),date=$('#agendaDate').value,kind=$('#agendaKind').value;
 if(!title||!/^\d{4}-\d{2}-\d{2}$/.test(date))return alert('Indica un título y una fecha válidos.');
 const original=JSON.stringify(data.agenda||[]);
 const value={title,date,kind,notes:$('#agendaNotes').value.trim(),unitId:$('#agendaUnit').value,classId:$('#agendaClass').value};
 if(editingAgendaId){const i=data.agenda.findIndex(x=>x.id===editingAgendaId);if(i<0)return;data.agenda[i]={...data.agenda[i],...value,updatedAt:new Date().toISOString()};}
 else data.agenda.push({id:uid(),...value,done:false,createdAt:new Date().toISOString()});
 try{await save();$('#agendaDialog').close();agendaView();showToast('Actividad guardada');}
 catch(err){data.agenda=JSON.parse(original);alert('No se pudo guardar la actividad: '+err.message);}
});
view.addEventListener('click',async e=>{
 const b=e.target.closest('[data-agenda]');if(!b)return;
 const op=b.dataset.agenda,id=b.dataset.id;
 if(op==='new')return openAgendaForm();if(op==='edit')return openAgendaForm(id);
 if(op==='filter'){agendaFilter=b.dataset.filter;agendaView();return;}
 if(op==='remove'&&!confirm('¿Eliminar esta actividad de la agenda?'))return;
 const original=JSON.stringify(data.agenda||[]),item=data.agenda.find(x=>x.id===id);if(!item)return;
 if(op==='remove')data.agenda=data.agenda.filter(x=>x.id!==id);
 if(op==='toggle')item.done=!item.done;
 try{await save();agendaView();showToast(op==='remove'?'Actividad eliminada':'Agenda actualizada');}
 catch(err){data.agenda=JSON.parse(original);alert('No fue posible guardar: '+err.message);}
});


// v0.5 — Intercambio explícito con ChatGPT; no usa API ni envía datos automáticamente.
const aiDialog=document.getElementById('aiDialog');
const aiResultDialog=document.getElementById('aiResultDialog');
let aiActiveDocId=null;
function validAINode(node,depth=0){return depth<=6&&node&&typeof node==='object'&&!Array.isArray(node)&&typeof node.label==='string'&&node.label.trim().length>0&&node.label.length<=240&&(!node.children||(Array.isArray(node.children)&&node.children.length<=15&&node.children.every(n=>validAINode(n,depth+1))))}
function validAIDocument(d){return !!(d&&typeof d.id==='string'&&typeof d.classId==='string'&&typeof d.title==='string'&&['summary','mindmap'].includes(d.type)&&(d.type==='summary'?typeof d.content==='string':validAINode(d.root)))}
function aiPanel(cls){const docs=(data.aiDocuments||[]).filter(x=>x.classId===cls.id);return `<section class="card ai-panel"><h2>Estudio asistido</h2><p class="muted">Prepara una solicitud para ChatGPT y luego importa el resultado. Nada se envía automáticamente.</p><div class="buttonrow"><button class="btn" data-action="ai-prepare">Preparar solicitud</button><button class="btn secondary" data-action="ai-import">Importar resultado</button></div><p class="hint">Los resultados se guardan en esta clase y se incluyen en el respaldo JSON.</p></section><section class="card"><h2>Mis resúmenes y mapas</h2>${docs.length?docs.map(d=>`<article class="ai-item"><div><strong>${esc(d.title)}</strong><p class="muted">${d.type==='mindmap'?'Mapa mental':'Resumen'} · ${esc((d.createdAt||'').slice(0,10))}</p></div><div class="buttonrow"><button class="btn secondary small" data-action="ai-open" data-id="${esc(d.id)}">Abrir</button><button class="btn danger small" data-action="ai-delete" data-id="${esc(d.id)}">Eliminar</button></div></article>`).join(''):'<p class="muted">Todavía no hay resultados importados.</p>'}</section>`}
function notePlainText(classId){const html=data.notes?.['class:'+classId]||'';const doc=new DOMParser().parseFromString(html,'text/html');doc.querySelectorAll('script,style').forEach(e=>e.remove());return (doc.body.innerText||doc.body.textContent||'').trim().slice(0,30000)}
function openAIRequest(){const c=data.classes.find(x=>x.id===activeClass);if(!c)return;document.getElementById('aiDialogTitle').textContent='Preparar solicitud';document.getElementById('aiPrepareArea').hidden=false;document.getElementById('aiImportArea').hidden=true;document.getElementById('aiRequestType').value='summary';document.getElementById('aiSource').value='notes';document.getElementById('aiExtra').value='';document.getElementById('aiPrompt').value='';document.getElementById('aiPromptWrap').hidden=true;aiDialog.showModal()}
function openAIImport(){document.getElementById('aiDialogTitle').textContent='Importar resultado';document.getElementById('aiPrepareArea').hidden=true;document.getElementById('aiImportArea').hidden=false;document.getElementById('aiImportText').value='';aiDialog.showModal()}
function makeAIPrompt(){const c=data.classes.find(x=>x.id===activeClass),unit=data.units.find(x=>x.id===c.unitId),type=document.getElementById('aiRequestType').value,source=document.getElementById('aiSource').value,extra=document.getElementById('aiExtra').value.trim();let notes=source==='paste'?'':notePlainText(c.id);if(source==='notes'&&!notes)throw Error('Esta clase todavía no tiene apuntes. Elige texto pegado.');if(source==='paste'&&!extra)throw Error('Pega un texto fuente primero.');const material=[notes?`APUNTES DE CLASE:\n${notes}`:'',extra?`TEXTO ADICIONAL:\n${extra}`:''].filter(Boolean).join('\n\n');const schema=type==='summary'?'{"type":"summary","title":"Título del resumen","content":"Resumen en texto con apartados y listas"}':'{"type":"mindmap","title":"Título del mapa","root":{"label":"Tema central","children":[{"label":"Concepto","children":[{"label":"Detalle"}]}]}}';const instruction=type==='summary'?'Escribe un resumen didáctico, organizado por subtítulos y listas; destaca definiciones y relaciones relevantes.':'Construye un mapa mental jerárquico de máximo 5 ramas principales, 3 niveles y etiquetas concisas.';return `Actúa como asistente académico. ${instruction} Usa únicamente la información suministrada, sin inventar datos; indica dentro del contenido lo que no esté claro. Devuelve EXCLUSIVAMENTE un objeto JSON válido, sin markdown ni bloques de código, con esta estructura exacta: ${schema}. No incluyas propiedades adicionales. Clase: ${c.title}. Unidad: ${unit?.title||'Sin unidad'}.\n\nMATERIAL FUENTE:\n${material}`}
function showAIPrompt(){try{const t=makeAIPrompt();document.getElementById('aiPrompt').value=t;document.getElementById('aiPromptWrap').hidden=false}catch(err){alert(err.message)}}
async function copyAIPrompt(){const text=document.getElementById('aiPrompt').value;if(!text)return;try{await navigator.clipboard.writeText(text);showToast('Solicitud copiada. Pégala en ChatGPT.')}catch{document.getElementById('aiPrompt').focus();document.getElementById('aiPrompt').select();alert('Copia el texto seleccionado y pégalo en ChatGPT.')}}
function parseAIJSON(input){let raw=input.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();const out=JSON.parse(raw);if(!out||!['summary','mindmap'].includes(out.type)||typeof out.title!=='string'||!out.title.trim()||out.title.length>160)throw Error('Título o tipo no válido.');if(out.type==='summary'&&(!out.content||typeof out.content!=='string'||out.content.length>100000))throw Error('El resumen está vacío o es demasiado largo.');if(out.type==='mindmap'&&!validAINode(out.root))throw Error('Estructura de mapa inválida (revisa etiquetas y ramas).');return out}
async function importAIResponse(){const text=document.getElementById('aiImportText').value;let doc;try{doc=parseAIJSON(text)}catch(err){alert('No se pudo interpretar el resultado: '+err.message);return}const record={id:uid(),classId:activeClass,type:doc.type,title:doc.title.trim(),...(doc.type==='summary'?{content:doc.content}:{root:doc.root}),createdAt:new Date().toISOString()};data.aiDocuments||=[];data.aiDocuments.push(record);try{await save();aiDialog.close();classDetail();showToast('Resultado importado y guardado')}catch(err){data.aiDocuments.pop();alert('Error al guardar: '+err.message)}}
function mapBranch(node){return `<li><span class="map-node">${esc(node.label)}</span>${node.children?.length?`<ul>${node.children.map(mapBranch).join('')}</ul>`:''}</li>`}
function mapOutline(node,depth=0){return `<div class="map-outline-row" style="padding-left:${Math.min(depth,6)*14}px"><span>${depth?'• ':'◉ '}${esc(node.label)}</span></div>${(node.children||[]).map(c=>mapOutline(c,depth+1)).join('')}`}
function openAIResult(id){const d=(data.aiDocuments||[]).find(x=>x.id===id);if(!d)return;aiActiveDocId=id;document.getElementById('aiResultTitle').textContent=d.title;document.getElementById('aiResultBody').innerHTML=d.type==='summary'?`<p class="hint">Puedes modificar el texto y guardar los cambios.</p><textarea id="aiEditSummary" rows="13">${esc(d.content)}</textarea>`:`<div class="buttonrow"><button class="btn secondary small" id="aiMapVisual">Visual</button><button class="btn secondary small" id="aiMapOutline">Esquema</button></div><div id="aiMapStage" class="map-stage"><div class="map-scroll"><ul class="mind-tree">${mapBranch(d.root)}</ul></div></div><details><summary>Editar estructura del mapa (JSON)</summary><p class="hint">Modifica las etiquetas y ramas manteniendo el formato JSON.</p><textarea rows="9" id="aiEditMap">${esc(JSON.stringify(d.root,null,2))}</textarea></details>`;aiResultDialog.showModal()}
function setMapView(mode){const d=(data.aiDocuments||[]).find(x=>x.id===aiActiveDocId);if(!d||d.type!=='mindmap')return;document.getElementById('aiMapStage').innerHTML=mode==='outline'?`<div class="map-outline">${mapOutline(d.root)}</div>`:`<div class="map-scroll"><ul class="mind-tree">${mapBranch(d.root)}</ul></div>`}
async function saveAIEdit(){const d=(data.aiDocuments||[]).find(x=>x.id===aiActiveDocId);if(!d)return;const before=JSON.stringify(d);try{if(d.type==='summary'){d.content=document.getElementById('aiEditSummary').value;if(!d.content.trim())throw Error('El texto está vacío.')}else{const parsed=JSON.parse(document.getElementById('aiEditMap').value);if(!validAINode(parsed))throw Error('Mapa inválido');d.root=parsed}d.updatedAt=new Date().toISOString();await save();aiResultDialog.close();classDetail();showToast('Cambios guardados')}catch(err){Object.assign(d,JSON.parse(before));alert('No se pudo guardar: '+err.message)}}
async function deleteAIResult(id){if(!confirm('¿Eliminar este resultado de estudio?'))return;const old=data.aiDocuments;data.aiDocuments=old.filter(x=>x.id!==id);try{await save();classDetail()}catch(err){data.aiDocuments=old;alert(err.message)}}
document.getElementById('aiClose').addEventListener('click',()=>aiDialog.close());
document.getElementById('aiShowPrompt').addEventListener('click',showAIPrompt);
document.getElementById('aiCopyPrompt').addEventListener('click',copyAIPrompt);
document.getElementById('aiSaveImport').addEventListener('click',importAIResponse);
document.getElementById('aiResultClose').addEventListener('click',()=>aiResultDialog.close());
document.getElementById('aiResultSave').addEventListener('click',saveAIEdit);
document.getElementById('aiResultBody').addEventListener('click',e=>{if(e.target.id==='aiMapVisual')setMapView('visual');if(e.target.id==='aiMapOutline')setMapView('outline')});
